window.KHO_DATA_L4_AMNHAC = [
{"lop":4,"mon":"Âm nhạc","tuan":1,"tiet":1,"bai":"Chủ đề 1: Âm thanh ngày mới — Lí thuyết âm nhạc: Làm quen với kí hiệu ghi nhạc; Đọc nhạc: Bài đọc nhạc số 1","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Bước đầu làm quen với khuông nhạc, khoá Son và vị trí các nốt nhạc.\n- Đọc đúng tên nốt, cao độ, trường độ Bài đọc nhạc số 1; biết đọc kết hợp gõ phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu thích môn Âm nhạc; cảm nhận vẻ tươi mới của âm thanh ngày mới.\n- Chăm chỉ, kiên trì luyện đọc nhạc.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc và ghi được kí hiệu về Làm quen với kí hiệu ghi nhạc nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe – bắt chước một vài âm thanh buổi sáng (tiếng chim, tiếng chuông) để khởi động giọng.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu khuông nhạc, khoá Son, vị trí một số nốt (Đô – Rê – Mi – Pha – Son – La).\n- GV hướng dẫn đọc Bài đọc nhạc số 1: đọc tên nốt, đọc cao độ theo thang âm/kí hiệu bàn tay.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đọc Bài đọc nhạc số 1 kết hợp gõ phách theo nhóm, cá nhân; GV sửa cao độ, trường độ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS đọc lại bài đọc nhạc trước lớp; nói tên vài nốt em đã nhớ.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng học liệu số về Làm quen với kí hiệu ghi nhạc: khuông nhạc hiện trên màn hình, GV kéo nốt lên xuống thì máy phát ngay âm thanh tương ứng, bấm vào hình nốt thì nghe được đúng độ dài của nốt đó — HS thấy được mối liên hệ giữa kí hiệu ghi trên giấy và âm thanh thật, điều mà nhìn hình in tĩnh trong sách không cho thấy.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ bài tập tương tác có chấm ngay về Làm quen với kí hiệu ghi nhạc: đặt nốt vào đúng vị trí trên khuông, chọn hình nốt đúng với tiếng gõ vừa nghe, chia ô nhịp cho đủ phách; sai ở đâu máy báo ngay, HS xem lại phần lí thuyết đúng chỗ đó rồi làm lại.\n⚠ (Miền 4: An toàn) Chỉ mở học liệu và phần mềm GV đã chuẩn bị sẵn trên máy của lớp, không mở trang khác trong giờ; làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép; ngồi cách màn hình vừa tầm mắt và nghỉ mắt sau mỗi 20 phút nhìn màn hình.","hs":"- HS đọc và ghi được kí hiệu về Làm quen với kí hiệu ghi nhạc nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.\n- HS làm bài tập tương tác, tự biết mình còn sai phần nào và ôn lại đúng phần đó."}]},
{"lop":4,"mon":"Âm nhạc","tuan":2,"tiet":2,"bai":"Chủ đề 1: Âm thanh ngày mới — Ôn đọc nhạc: Bài đọc nhạc số 1; Học hát: Chuông gió leng keng (Nhạc và lời: Lê Vinh Phúc)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Đọc thuộc, đọc đúng Bài đọc nhạc số 1 kết hợp gõ phách.\n- Hát đúng cao độ, trường độ, lời ca bài Chuông gió leng keng; thể hiện tính chất vui tươi, trong sáng.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu cuộc sống; cảm nhận vẻ đẹp của những âm thanh quanh em.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp đọc lại Bài đọc nhạc số 1 kết hợp gõ phách để khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn nhanh bài đọc nhạc; sửa chỗ HS còn đọc sai.\n- GV giới thiệu, hát mẫu bài Chuông gió leng keng; hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca theo tiết tấu, chia câu, dạy hát nối tiếp từng câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp vỗ tay theo phách; luyện theo tổ, nhóm, cá nhân; GV sửa cao độ, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát lại bài cho người thân nghe; kể một âm thanh vui tai em thường nghe vào buổi sáng.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Chuông gió leng keng” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Lê Vinh Phúc”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Chuông gió leng keng” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Chuông gió leng keng” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Chuông gió leng keng” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":3,"tiet":3,"bai":"Chủ đề 1: Âm thanh ngày mới — Ôn tập bài hát Chuông gió leng keng; Thường thức âm nhạc: Hình thức biểu diễn trong ca hát","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, biểu diễn được bài Chuông gió leng keng với hình thức phù hợp.\n- Nhận biết một số hình thức biểu diễn ca hát: đơn ca, song ca, tốp ca, đồng ca.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Tự tin biểu diễn; yêu thích ca hát.\n- Hợp tác, tôn trọng bạn khi biểu diễn nhóm.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được đặc điểm nổi bật của “Hình thức biểu diễn trong ca hát” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Chuông gió leng keng kết hợp vỗ tay để khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, sửa sai bài hát; hướng dẫn hát kết hợp vận động phụ hoạ.\n- GV giới thiệu các hình thức biểu diễn: đơn ca, song ca, tốp ca, đồng ca; cho HS xem hình ảnh/clip minh hoạ.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện biểu diễn bài hát theo các hình thức khác nhau (đơn ca, song ca, tốp ca) theo nhóm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp và gọi tên hình thức biểu diễn nhóm mình vừa thể hiện.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu vài đoạn phim ngắn cho nội dung “Hình thức biểu diễn trong ca hát”, mỗi đoạn một cách trình bày khác nhau, đặt cạnh nhau trên cùng màn hình; HS so sánh số người tham gia, cách đứng, cách vào bài và chỉ ra điểm khác nhau — xem trực tiếp nhiều đoạn trong vài phút là điều lời giảng suông không thay được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập tương tác có chấm ngay về “Hình thức biểu diễn trong ca hát”: nghe một đoạn rồi chọn đúng tên cách trình bày, nối tên với hình minh hoạ; chọn sai thì xem lại đoạn phim tương ứng rồi chọn lần nữa.\n⚠ (Miền 4: An toàn) Tư liệu về “Hình thức biểu diễn trong ca hát” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Hình thức biểu diễn trong ca hát” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":4,"tiet":4,"bai":"Chủ đề 1: Âm thanh ngày mới — Vận dụng – Sáng tạo (Tổng kết chủ đề 1)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Vận dụng kiến thức, kĩ năng của chủ đề: đọc nhạc, hát, hình thức biểu diễn.\n- Biết phối hợp hát, gõ đệm, vận động thành tiết mục biểu diễn đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Tự tin biểu diễn; đoàn kết, hợp tác trong nhóm.\n- Yêu thích môn Âm nhạc.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc ôn lại nội dung chủ đề (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống lại nội dung chủ đề 1: bài đọc nhạc, bài hát, hình thức biểu diễn.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục kết hợp hát – gõ đệm – vận động.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục biểu diễn theo phân công; GV quan sát, hỗ trợ, khích lệ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; bình chọn tiết mục ấn tượng; GV nhận xét, tổng kết chủ đề.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":5,"tiet":5,"bai":"Chủ đề 2: Giai điệu quê hương — Học hát: Chim sáo (Dân ca Khơ-me – Nam Bộ, sưu tầm: Đặng Nguyễn)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời ca bài Chim sáo; cảm nhận nét mộc mạc, vui tươi của dân ca.\n- Biết hát kết hợp gõ đệm theo phách/nhịp.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quý và tự hào về dân ca các dân tộc Việt Nam.\n- Chăm chỉ luyện tập, giữ gìn bản sắc văn hoá dân tộc.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe một câu dân ca quen thuộc, hỏi các em đã từng nghe bài dân ca nào của Nam Bộ chưa.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu bài dân ca Khơ-me Chim sáo; hát mẫu, hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca, chia câu, dạy hát nối tiếp từng câu; nhắc HS hát nhẹ nhàng, thể hiện nét dân ca.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS hát cả bài kết hợp gõ đệm theo phách; luyện theo tổ, nhóm, cá nhân; GV sửa cao độ, tiết tấu.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS chia sẻ cảm nhận về bài dân ca; kể tên vùng miền có dân ca mà em biết.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Chim sáo” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Dân ca Khơ-me – Nam Bộ, sưu tầm: Đặng Nguyễn”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Chim sáo” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Chim sáo” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Chim sáo” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":6,"tiet":6,"bai":"Chủ đề 2: Giai điệu quê hương — Ôn tập bài hát Chim sáo; Nhạc cụ: Thể hiện nhạc cụ gõ hoặc nhạc cụ giai điệu","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được bài Chim sáo với hình thức phù hợp.\n- Nhận biết cách chơi cơ bản của nhạc cụ gõ/nhạc cụ giai điệu; thể hiện hình tiết tấu, đệm cho bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Chăm chỉ luyện tập nhạc cụ; giữ gìn, bảo quản nhạc cụ.\n- Tôn trọng, hợp tác cùng bạn khi hoà tấu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV vỗ tay/gõ một hình tiết tấu ngắn, HS nghe và bắt chước lại.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, sửa sai bài hát Chim sáo; hướng dẫn biểu diễn theo nhóm.\n- GV giới thiệu cách cầm, cách gõ/bấm nhạc cụ; làm mẫu hình tiết tấu, hướng dẫn HS đọc và thực hiện theo.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện gõ/bấm hình tiết tấu theo nhóm; ghép đệm cho bài Chim sáo; GV sửa cho HS thực hiện đều, đúng phách.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp gõ đệm; nhóm khác nhận xét.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":7,"tiet":7,"bai":"Chủ đề 2: Giai điệu quê hương — Thường thức âm nhạc: Giới thiệu đàn tranh; Nghe nhạc: Lí ngựa ô (Dân ca Nam Bộ)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết hình dáng, âm sắc của đàn tranh.\n- Lắng nghe, cảm nhận tính chất, sắc thái bản nhạc Lí ngựa ô; biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quý nhạc cụ dân tộc; trân trọng âm nhạc truyền thống.\n- Biết lắng nghe, cảm thụ âm nhạc.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được đặc điểm nổi bật của “Giới thiệu đàn tranh” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe một đoạn nhạc do đàn tranh thể hiện, hỏi cảm nhận về âm sắc.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu đàn tranh: hình dáng, số dây, cách chơi cơ bản; cho HS quan sát hình ảnh/clip.\n- GV cho HS nghe bản nhạc Lí ngựa ô; gợi ý HS chú ý nhịp điệu, sắc thái.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại bản nhạc và vận động cơ thể theo nhịp; tập nhận ra âm sắc đàn tranh.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận sau khi nghe; kể tên một nhạc cụ dân tộc khác mà em biết.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu đoạn phim quay cận cảnh cho nội dung “Giới thiệu đàn tranh”: nhìn rõ hình dáng, chất liệu, số dây hoặc số lỗ, bàn tay nghệ sĩ đặt ở đâu và làm động tác gì để ra tiếng; GV tua chậm và dừng đúng chỗ đó — chi tiết này tranh in trong sách và một lần nghe trên lớp không cho thấy được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập nghe tương tác có chấm ngay: GV mở lần lượt vài đoạn nhạc ngắn, HS chọn đoạn nào có âm sắc của nhạc cụ vừa học trong “Giới thiệu đàn tranh”; chọn sai thì nghe lại đoạn đó và chọn lần nữa cho tới khi nhận ra đúng.\n⚠ (Miền 4: An toàn) Tư liệu về “Giới thiệu đàn tranh” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Giới thiệu đàn tranh” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":8,"tiet":8,"bai":"Chủ đề 2: Giai điệu quê hương — Vận dụng – Sáng tạo (Tổng kết chủ đề 2)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Vận dụng kiến thức, kĩ năng chủ đề: hát dân ca, nhạc cụ, nghe nhạc.\n- Biết dàn dựng tiết mục hát dân ca kết hợp gõ đệm hoặc nhạc cụ.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Tự hào, giữ gìn dân ca; tự tin biểu diễn.\n- Đoàn kết, hợp tác.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi nghe tiết tấu/giai điệu đoán tên bài đã học trong chủ đề.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung chủ đề 2.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục hát dân ca kết hợp gõ đệm/nhạc cụ.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục theo phân công; GV hỗ trợ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn; lớp nhận xét, bình chọn; GV tổng kết chủ đề.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":9,"tiet":9,"bai":"Chủ đề 3: Thầy cô với chúng em — Lí thuyết âm nhạc: Giới thiệu các hình nốt; Đọc nhạc: Bài đọc nhạc số 2","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết một số hình nốt nhạc (nốt trắng, nốt đen, móc đơn) và giá trị trường độ.\n- Đọc đúng tên nốt, cao độ, trường độ Bài đọc nhạc số 2; biết đọc kết hợp gõ phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Chăm chỉ, kiên trì luyện đọc nhạc.\n- Yêu thích môn Âm nhạc.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc và ghi được kí hiệu về Giới thiệu các hình nốt nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS vỗ tay theo một mẫu tiết tấu dài – ngắn để khởi động, dẫn vào bài về hình nốt.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu các hình nốt (nốt trắng, nốt đen, móc đơn) và độ dài tương ứng.\n- GV hướng dẫn Bài đọc nhạc số 2: đọc tên nốt, đọc cao độ kết hợp trường độ.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đọc Bài đọc nhạc số 2 kết hợp gõ phách theo nhóm, cá nhân; GV sửa cao độ, trường độ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS đọc lại bài đọc nhạc; phân biệt nốt dài – nốt ngắn qua vài ví dụ.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng học liệu số về Giới thiệu các hình nốt: khuông nhạc hiện trên màn hình, GV kéo nốt lên xuống thì máy phát ngay âm thanh tương ứng, bấm vào hình nốt thì nghe được đúng độ dài của nốt đó — HS thấy được mối liên hệ giữa kí hiệu ghi trên giấy và âm thanh thật, điều mà nhìn hình in tĩnh trong sách không cho thấy.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ bài tập tương tác có chấm ngay về Giới thiệu các hình nốt: đặt nốt vào đúng vị trí trên khuông, chọn hình nốt đúng với tiếng gõ vừa nghe, chia ô nhịp cho đủ phách; sai ở đâu máy báo ngay, HS xem lại phần lí thuyết đúng chỗ đó rồi làm lại.\n⚠ (Miền 4: An toàn) Chỉ mở học liệu và phần mềm GV đã chuẩn bị sẵn trên máy của lớp, không mở trang khác trong giờ; làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép; ngồi cách màn hình vừa tầm mắt và nghỉ mắt sau mỗi 20 phút nhìn màn hình.","hs":"- HS đọc và ghi được kí hiệu về Giới thiệu các hình nốt nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.\n- HS làm bài tập tương tác, tự biết mình còn sai phần nào và ôn lại đúng phần đó."}]},
{"lop":4,"mon":"Âm nhạc","tuan":10,"tiet":10,"bai":"Chủ đề 3: Thầy cô với chúng em — Học hát: Nếu em là... (Nhạc và lời: Trương Quang Lục)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời bài Nếu em là...; thể hiện tình cảm trong sáng, tha thiết.\n- Biết hát kết hợp vỗ tay/gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Biết ơn, kính trọng thầy cô giáo.\n- Chăm chỉ, tích cực trong học tập và rèn luyện.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS xem hình ảnh ngày Nhà giáo Việt Nam; hỏi các em làm gì để tỏ lòng biết ơn thầy cô.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu, hát mẫu bài Nếu em là...; hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca, chia câu; dạy hát nối tiếp từng câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS hát cả bài kết hợp gõ đệm theo phách; luyện theo tổ, nhóm, cá nhân; GV sửa sai.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài hát dành tặng thầy cô; nói lời tri ân thầy cô của mình.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Nếu em là...” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Trương Quang Lục”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Nếu em là...” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Nếu em là...” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Nếu em là...” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":11,"tiet":11,"bai":"Chủ đề 3: Thầy cô với chúng em — Ôn tập bài hát Nếu em là...; Nghe nhạc: Điều mong ước tặng thầy (Nhạc: Bùi Anh Tôn)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được bài Nếu em là... với hình thức phù hợp.\n- Lắng nghe, cảm nhận nội dung, tình cảm bài Điều mong ước tặng thầy; biết vận động nhẹ theo nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Biết ơn, kính yêu thầy cô.\n- Biết lắng nghe và trân trọng âm nhạc.\n4. Tích hợp\n- Năng lực số 1.2 CB2a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Nếu em là... kết hợp vỗ tay khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, sửa sai bài hát; hướng dẫn biểu diễn.\n- GV cho HS nghe bài Điều mong ước tặng thầy; gợi ý HS chú ý lời ca, tình cảm bài hát.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS biểu diễn bài hát theo nhóm; nghe lại và vận động nhẹ nhàng theo bài nghe nhạc.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS chia sẻ cảm xúc sau khi nghe; hứa với thầy cô một việc tốt sẽ làm.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản ghi hình buổi biểu diễn tác phẩm “Điều mong ước tặng thầy” (Nhạc: Bùi Anh Tôn); HS vừa nghe vừa quan sát để nhận ra nhạc cụ nào giữ giai điệu chính, đoạn nào nhạc mạnh lên, đoạn nào chậm lại và ai là người bắt nhịp cho cả dàn nhạc — những điều chỉ nghe bản thu tiếng thì không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở thêm một đoạn nhạc do máy tự sinh theo phong cách gần giống rồi cho HS nghe đối chiếu với bản do nghệ sĩ biểu diễn; HS nêu chỗ khác nhau về sắc thái to nhỏ, chỗ nhanh chậm và nhận ra máy ghép lại theo những bản nhạc nó đã học nên chưa có cảm xúc của người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản ghi hình “Điều mong ước tặng thầy” phải lấy từ kênh chính thức của nhà hát, dàn nhạc hoặc nhà xuất bản và tải về trước để không lẫn quảng cáo; khi nói hoặc viết về tác phẩm phải ghi tên tác giả và tên người biểu diễn, không cắt nhạc của người khác đem dùng khi chưa được phép; nghe bằng loa ở mức vừa, không đeo tai nghe mở to lâu.","hs":"- HS nêu được nét đặc sắc của tác phẩm “Điều mong ước tặng thầy” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.\n- HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày."}]},
{"lop":4,"mon":"Âm nhạc","tuan":12,"tiet":12,"bai":"Chủ đề 3: Thầy cô với chúng em — Vận dụng – Sáng tạo (Tổng kết chủ đề 3)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Vận dụng kiến thức, kĩ năng chủ đề: hình nốt, đọc nhạc, hát, nghe nhạc.\n- Biết phối hợp hát, gõ đệm, vận động thành tiết mục biểu diễn tri ân thầy cô.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Biết ơn thầy cô; tự tin biểu diễn.\n- Đoàn kết, hợp tác trong nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc ôn lại nội dung chủ đề (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung chủ đề 3.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục hát tri ân thầy cô kết hợp gõ đệm/vận động.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục theo phân công; GV hỗ trợ, khích lệ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; bình chọn tiết mục ý nghĩa; GV nhận xét, tổng kết chủ đề.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":13,"tiet":13,"bai":"Chủ đề 4: Vui đón Tết — Học hát: Tết là Tết (Nhạc và lời: Nhất Trung)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Tết là Tết; thể hiện tính chất rộn ràng, vui tươi.\n- Biết hát kết hợp vỗ tay/gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quê hương, yêu ngày Tết cổ truyền dân tộc.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS xem hình ảnh không khí ngày Tết; hỏi các em thích điều gì nhất trong ngày Tết.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu, hát mẫu bài Tết là Tết; hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp vỗ tay theo phách; luyện theo tổ, nhóm, cá nhân; GV sửa cao độ, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát lại bài cho người thân nghe; kể một hoạt động ngày Tết ở gia đình em.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Tết là Tết” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Nhất Trung”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Tết là Tết” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Tết là Tết” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Tết là Tết” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":14,"tiet":14,"bai":"Chủ đề 4: Vui đón Tết — Ôn tập bài hát Tết là Tết; Nhạc cụ: Thể hiện nhạc cụ gõ hoặc nhạc cụ giai điệu","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được bài Tết là Tết với hình thức phù hợp.\n- Thể hiện hình tiết tấu bằng nhạc cụ gõ/nhạc cụ giai điệu; biết đệm cho bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu ngày Tết; tự tin biểu diễn.\n- Chăm chỉ luyện tập, hợp tác cùng bạn.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Tết là Tết kết hợp vỗ tay khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, sửa sai bài hát; hướng dẫn hát kết hợp vận động.\n- GV làm mẫu hình tiết tấu bằng nhạc cụ; hướng dẫn HS đọc và thực hiện theo.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện gõ/bấm hình tiết tấu; ghép đệm cho bài Tết là Tết theo nhóm; GV sửa cho đều, đúng phách.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp gõ đệm; nhóm khác nhận xét.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":15,"tiet":15,"bai":"Chủ đề 4: Vui đón Tết — Thường thức âm nhạc: Câu chuyện âm nhạc Pi-tơ và chó sói (Phỏng theo: Séc-gây Pơ-rô-cô-phi-ép)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết nội dung câu chuyện âm nhạc Pi-tơ và chó sói.\n- Bước đầu nhận biết một số nhạc cụ thể hiện nhân vật trong tác phẩm qua âm sắc.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu thích âm nhạc; biết lắng nghe, cảm thụ.\n- Dũng cảm, thông minh như nhân vật trong truyện.\n4. Tích hợp\n- Năng lực số 5.1 CB2a: Xác định được các vấn đề kỹ thuật đơn giản khi vận hành thiết bị và sử dụng môi trường số: HS nêu được đặc điểm nổi bật của “Câu chuyện âm nhạc Pi-tơ và chó sói (Phỏng theo: Séc-gây Pơ-rô-cô-phi-ép)” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe một đoạn nhạc mô phỏng tiếng động vật, hỏi các em đoán con vật.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV kể câu chuyện âm nhạc Pi-tơ và chó sói; giới thiệu ngắn về tác giả (nhạc sĩ Séc-gây Pơ-rô-cô-phi-ép, người Nga).\n- GV cho HS nghe trích đoạn, gợi ý nhận ra âm sắc nhạc cụ ứng với từng nhân vật.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại trích đoạn và nối nhạc cụ với nhân vật theo gợi ý; kể lại một đoạn truyện.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS chia sẻ cảm nhận về câu chuyện; nêu bài học em rút ra.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản kể chuyện có nhạc minh hoạ cho “Câu chuyện âm nhạc Pi-tơ và chó sói (Phỏng theo: Séc-gây Pơ-rô-cô-phi-ép)”, dừng lại ở mỗi lần một nhân vật xuất hiện để HS nghe kĩ nhạc cụ nào đang thay lời nhân vật đó; nhờ nghe đi nghe lại đúng đoạn, HS nhận ra âm nhạc đang kể chuyện chứ không chỉ làm nền.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập tương tác có chấm ngay về “Câu chuyện âm nhạc Pi-tơ và chó sói (Phỏng theo: Séc-gây Pơ-rô-cô-phi-ép)”: nghe đoạn nhạc rồi chọn đúng nhân vật, sắp lại thứ tự diễn biến câu chuyện; sai chỗ nào HS nghe lại đúng đoạn nhạc đó rồi chọn lần nữa.\n⚠ (Miền 4: An toàn) Tư liệu về “Câu chuyện âm nhạc Pi-tơ và chó sói (Phỏng theo: Séc-gây Pơ-rô-cô-phi-ép)” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Câu chuyện âm nhạc Pi-tơ và chó sói (Phỏng theo: Séc-gây Pơ-rô-cô-phi-ép)” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":16,"tiet":16,"bai":"Chủ đề 4: Vui đón Tết — Vận dụng – Sáng tạo (Tổng kết chủ đề 4)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Vận dụng kiến thức, kĩ năng chủ đề: hát, nhạc cụ, câu chuyện âm nhạc.\n- Biết dàn dựng tiết mục mừng xuân kết hợp hát – gõ đệm – vận động.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu ngày Tết; tự tin biểu diễn.\n- Đoàn kết, hợp tác trong nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc chủ đề ngày Tết (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung chủ đề 4.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục mừng xuân kết hợp hát – gõ đệm – vận động.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục theo phân công; GV hỗ trợ, khích lệ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; bình chọn tiết mục ấn tượng; GV nhận xét, tổng kết chủ đề.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":17,"tiet":17,"bai":"Ôn tập cuối học kì I (Tiết 1)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được các bài hát đã học ở học kì I (Chuông gió leng keng, Chim sáo, Nếu em là..., Tết là Tết).\n- Đọc đúng các Bài đọc nhạc số 1, số 2; ôn lại kiến thức lí thuyết, thường thức âm nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Chăm chỉ ôn tập; tự tin thể hiện.\n- Yêu thích môn Âm nhạc.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc ôn lại các bài hát học kì I (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung học kì I: các bài hát, bài đọc nhạc, lí thuyết, thường thức âm nhạc.\n- GV cho HS ôn lần lượt từng bài hát và bài đọc nhạc; sửa sai.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện hát – đọc nhạc theo tổ, nhóm; luyện biểu diễn một bài tự chọn.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS biểu diễn bài hát/bài đọc nhạc yêu thích trước lớp.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":18,"tiet":18,"bai":"Ôn tập cuối học kì I (Tiết 2) – Biểu diễn tổng kết","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn được các bài hát, bài đọc nhạc đã học ở học kì I với hình thức phong phú.\n- Phối hợp hát, gõ đệm, vận động; tự đánh giá kết quả học tập học kì I.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Tự tin biểu diễn; đoàn kết, hợp tác.\n- Yêu thích môn Âm nhạc.\n4. Tích hợp\n- Năng lực số 3.3 CB2a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS giới thiệu sản phẩm của tổ đúng phép lịch sự, có ghi tên tác giả và xin phép bạn trước khi chia sẻ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại một bài học kì I kết hợp vỗ tay để khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV nêu yêu cầu biểu diễn tổng kết; chia nhóm, giao nhiệm vụ chuẩn bị tiết mục.\n- GV gợi ý cách phối hợp hát – gõ đệm – vận động cho tiết mục.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục biểu diễn tổng kết học kì I; GV hỗ trợ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; lớp nhận xét, bình chọn; GV nhận xét, đánh giá, tổng kết học kì I.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Mỗi tổ tự quay lại phần biểu diễn học kì I của mình bằng điện thoại hoặc máy tính của lớp, xem lại và ghi ra hai điều tổ đã làm tốt, một điều cần sửa, rồi quay lần hai để đối chiếu xem đã khá hơn ở chỗ nào.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ câu hỏi tương tác có chấm ngay ôn lại học kì I: nghe đoạn nhạc nhận ra bài hát, đọc kí hiệu ghi nhạc, gọi tên nhạc cụ qua âm sắc; HS tự nhìn kết quả để biết phần nào mình còn sai nhiều mà ôn lại đúng phần đó.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) Các tổ đổi bản quay cho nhau qua nhóm lớp và viết cho tổ bạn hai câu nhận xét: một câu khen chỗ bạn làm tốt, một câu góp ý chỗ nên sửa; HS tập viết nhận xét trên nhóm đúng mực như khi nói trực tiếp với bạn.\n⚠ (Miền 4: An toàn) Đoạn phim có mặt bạn chỉ được gửi khi từng bạn trong đó đồng ý và chỉ gửi trong nhóm lớp, không đăng ra mạng xã hội; giới thiệu bài hát phải ghi tên tác giả, không nhận bài của người khác là của mình; góp ý cho bạn bằng lời lịch sự, viết trong nhóm cũng phải như nói trước mặt.","hs":"- HS tự quay, xem lại và nêu được điều tổ mình đã sửa được giữa hai lần trình bày.\n- HS giới thiệu sản phẩm của tổ đúng phép lịch sự, có ghi tên tác giả và xin phép bạn trước khi chia sẻ."}]},
{"lop":4,"mon":"Âm nhạc","tuan":19,"tiet":19,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Lí thuyết âm nhạc: Dấu lặng; Đọc nhạc: Bài đọc nhạc số 3","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết dấu lặng và ý nghĩa nghỉ trong âm nhạc.\n- Đọc đúng tên nốt, cao độ, trường độ Bài đọc nhạc số 3; biết đọc kết hợp gõ phách, ngắt nghỉ đúng dấu lặng.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên; chăm chỉ luyện đọc nhạc.\n- Kiên trì, tự tin thể hiện.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc và ghi được kí hiệu về Dấu lặng nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS chơi trò vỗ tay – dừng theo hiệu lệnh để cảm nhận sự nghỉ (dẫn vào dấu lặng).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu dấu lặng và ý nghĩa nghỉ; minh hoạ bằng ví dụ.\n- GV hướng dẫn Bài đọc nhạc số 3: đọc tên nốt, đọc cao độ, ngắt nghỉ đúng chỗ có dấu lặng.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đọc Bài đọc nhạc số 3 kết hợp gõ phách theo nhóm, cá nhân; GV sửa cao độ, trường độ, ngắt nghỉ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS đọc lại bài đọc nhạc; chỉ ra chỗ có dấu lặng trong bài.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng học liệu số về Dấu lặng: khuông nhạc hiện trên màn hình, GV kéo nốt lên xuống thì máy phát ngay âm thanh tương ứng, bấm vào hình nốt thì nghe được đúng độ dài của nốt đó — HS thấy được mối liên hệ giữa kí hiệu ghi trên giấy và âm thanh thật, điều mà nhìn hình in tĩnh trong sách không cho thấy.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ bài tập tương tác có chấm ngay về Dấu lặng: đặt nốt vào đúng vị trí trên khuông, chọn hình nốt đúng với tiếng gõ vừa nghe, chia ô nhịp cho đủ phách; sai ở đâu máy báo ngay, HS xem lại phần lí thuyết đúng chỗ đó rồi làm lại.\n⚠ (Miền 4: An toàn) Chỉ mở học liệu và phần mềm GV đã chuẩn bị sẵn trên máy của lớp, không mở trang khác trong giờ; làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép; ngồi cách màn hình vừa tầm mắt và nghỉ mắt sau mỗi 20 phút nhìn màn hình.","hs":"- HS đọc và ghi được kí hiệu về Dấu lặng nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.\n- HS làm bài tập tương tác, tự biết mình còn sai phần nào và ôn lại đúng phần đó."}]},
{"lop":4,"mon":"Âm nhạc","tuan":20,"tiet":20,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Học hát: Hạt mưa kể chuyện (Nhạc và lời: Huỳnh Ngọc La Sơn)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời bài Hạt mưa kể chuyện; thể hiện tính chất nhẹ nhàng, trong sáng.\n- Biết hát kết hợp vỗ tay/gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên, biết bảo vệ môi trường.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe âm thanh tiếng mưa, hỏi cảm nhận và dẫn vào bài.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu, hát mẫu bài Hạt mưa kể chuyện; hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp vỗ tay theo phách; luyện theo tổ, nhóm, cá nhân; GV sửa cao độ, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát lại bài cho người thân nghe; kể một điều thú vị về mưa và thiên nhiên.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Hạt mưa kể chuyện” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Huỳnh Ngọc La Sơn”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Hạt mưa kể chuyện” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Hạt mưa kể chuyện” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Hạt mưa kể chuyện” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":21,"tiet":21,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Ôn tập bài hát Hạt mưa kể chuyện; Nghe nhạc: Không gian xanh (Nguyễn Đức Hiệt)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được bài Hạt mưa kể chuyện với hình thức phù hợp.\n- Lắng nghe, cảm nhận tính chất, sắc thái bản nhạc Không gian xanh; biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên, bảo vệ môi trường xanh.\n- Biết lắng nghe và trân trọng âm nhạc.\n4. Tích hợp\n- Năng lực số 1.2 CB2a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Hạt mưa kể chuyện kết hợp vận động khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, sửa sai bài hát; hướng dẫn biểu diễn theo nhóm.\n- GV cho HS nghe bản nhạc Không gian xanh; gợi ý HS chú ý nhịp điệu, sắc thái, nội dung về thiên nhiên.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS biểu diễn bài hát theo nhóm; nghe lại bản nhạc và vận động cơ thể theo nhịp.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận sau khi nghe; nêu một việc em làm để giữ gìn môi trường xanh.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản ghi hình buổi biểu diễn tác phẩm “Không gian xanh” (Nguyễn Đức Hiệt); HS vừa nghe vừa quan sát để nhận ra nhạc cụ nào giữ giai điệu chính, đoạn nào nhạc mạnh lên, đoạn nào chậm lại và ai là người bắt nhịp cho cả dàn nhạc — những điều chỉ nghe bản thu tiếng thì không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở thêm một đoạn nhạc do máy tự sinh theo phong cách gần giống rồi cho HS nghe đối chiếu với bản do nghệ sĩ biểu diễn; HS nêu chỗ khác nhau về sắc thái to nhỏ, chỗ nhanh chậm và nhận ra máy ghép lại theo những bản nhạc nó đã học nên chưa có cảm xúc của người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản ghi hình “Không gian xanh” phải lấy từ kênh chính thức của nhà hát, dàn nhạc hoặc nhà xuất bản và tải về trước để không lẫn quảng cáo; khi nói hoặc viết về tác phẩm phải ghi tên tác giả và tên người biểu diễn, không cắt nhạc của người khác đem dùng khi chưa được phép; nghe bằng loa ở mức vừa, không đeo tai nghe mở to lâu.","hs":"- HS nêu được nét đặc sắc của tác phẩm “Không gian xanh” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.\n- HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày."}]},
{"lop":4,"mon":"Âm nhạc","tuan":22,"tiet":22,"bai":"Chủ đề 5: Thiên nhiên tươi đẹp — Vận dụng – Sáng tạo (Tổng kết chủ đề 5)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Vận dụng kiến thức, kĩ năng chủ đề: dấu lặng, đọc nhạc, hát, nghe nhạc.\n- Biết dàn dựng tiết mục về thiên nhiên kết hợp hát – gõ đệm – vận động.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu thiên nhiên; tự tin biểu diễn.\n- Đoàn kết, hợp tác trong nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc chủ đề thiên nhiên (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung chủ đề 5.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục về thiên nhiên kết hợp hát – gõ đệm – vận động.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục theo phân công; GV hỗ trợ, khích lệ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; bình chọn tiết mục ấn tượng; GV nhận xét, tổng kết chủ đề.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":23,"tiet":23,"bai":"Chủ đề 6: Tình bạn tuổi thơ — Học hát: Tình bạn tuổi thơ (Nhạc và lời: Nguyễn Quốc Việt)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời bài Tình bạn tuổi thơ; thể hiện tính chất vui tươi, thân thiết.\n- Biết hát kết hợp vỗ tay/gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quý bạn bè; sống chan hoà, đoàn kết.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS xem hình ảnh các bạn cùng chơi, hỏi các em thường chơi gì cùng bạn thân.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu, hát mẫu bài Tình bạn tuổi thơ; hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp vỗ tay theo phách; luyện theo tổ, nhóm, cá nhân; GV sửa cao độ, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát bài hát cùng bạn thân; nói một điều em quý ở người bạn của mình.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Tình bạn tuổi thơ” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Nguyễn Quốc Việt”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Tình bạn tuổi thơ” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Tình bạn tuổi thơ” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Tình bạn tuổi thơ” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":24,"tiet":24,"bai":"Chủ đề 6: Tình bạn tuổi thơ — Ôn tập bài hát Tình bạn tuổi thơ; Thường thức âm nhạc: Nhạc sĩ Lưu Hữu Phước và bài hát Reo vang bình minh","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được bài Tình bạn tuổi thơ với hình thức phù hợp.\n- Nhận biết đôi nét về nhạc sĩ Lưu Hữu Phước; cảm nhận bài hát Reo vang bình minh.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quý bạn bè; trân trọng các nhạc sĩ và tác phẩm âm nhạc Việt Nam.\n- Biết lắng nghe, cảm thụ âm nhạc.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được đặc điểm nổi bật của “Nhạc sĩ Lưu Hữu Phước và bài hát Reo vang bình minh” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Tình bạn tuổi thơ kết hợp vỗ tay khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, sửa sai bài hát; hướng dẫn biểu diễn.\n- GV giới thiệu đôi nét về nhạc sĩ Lưu Hữu Phước; cho HS nghe bài Reo vang bình minh, gợi ý cảm nhận.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS biểu diễn bài hát theo nhóm; nghe lại bài Reo vang bình minh và vận động nhẹ theo nhạc.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS chia sẻ cảm nhận về bài Reo vang bình minh; kể một điều em nhớ về nhạc sĩ Lưu Hữu Phước.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu tư liệu số về “Nhạc sĩ Lưu Hữu Phước và bài hát Reo vang bình minh”: ảnh chân dung, mốc thời gian cuộc đời và bản thu những tác phẩm tiêu biểu lấy từ trang chính thống; HS nghe hai bài của cùng nhạc sĩ rồi nói bài nào em thích hơn và vì sao — nghe được tác phẩm thật khác hẳn chỉ đọc mấy dòng tiểu sử.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập tương tác có chấm ngay về “Nhạc sĩ Lưu Hữu Phước và bài hát Reo vang bình minh”: nối tên bài hát với tên nhạc sĩ, sắp các mốc thời gian cho đúng thứ tự, nghe đoạn nhạc và chọn tên bài; sai câu nào HS mở lại đúng phần tư liệu của câu đó.\n⚠ (Miền 4: An toàn) Tư liệu về “Nhạc sĩ Lưu Hữu Phước và bài hát Reo vang bình minh” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Nhạc sĩ Lưu Hữu Phước và bài hát Reo vang bình minh” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":25,"tiet":25,"bai":"Chủ đề 6: Tình bạn tuổi thơ — Nhạc cụ: Thể hiện nhạc cụ gõ hoặc nhạc cụ giai điệu","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Thể hiện được hình tiết tấu/mẫu âm bằng nhạc cụ gõ hoặc nhạc cụ giai điệu.\n- Biết dùng nhạc cụ đệm cho bài hát Tình bạn tuổi thơ.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Chăm chỉ, kiên trì luyện tập nhạc cụ; giữ gìn, bảo quản nhạc cụ.\n- Hợp tác cùng bạn khi hoà tấu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV vỗ tay/gõ một hình tiết tấu ngắn, HS nghe và bắt chước lại.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV làm mẫu hình tiết tấu/mẫu âm bằng nhạc cụ; hướng dẫn HS đọc và thực hiện theo từng bước.\n- GV nhắc tư thế cầm, cách gõ/bấm nhạc cụ đúng và an toàn.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện gõ/bấm hình tiết tấu; ghép đệm cho bài Tình bạn tuổi thơ theo nhóm; GV sửa cho đều, đúng phách.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp gõ đệm; nhóm khác nhận xét.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":26,"tiet":26,"bai":"Chủ đề 6: Tình bạn tuổi thơ — Vận dụng – Sáng tạo (Tổng kết chủ đề 6)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Vận dụng kiến thức, kĩ năng chủ đề: hát, thường thức âm nhạc, nhạc cụ.\n- Biết dàn dựng tiết mục về tình bạn kết hợp hát – gõ đệm – vận động.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quý bạn bè; tự tin biểu diễn.\n- Đoàn kết, hợp tác trong nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc chủ đề tình bạn (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung chủ đề 6.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục về tình bạn kết hợp hát – gõ đệm – vận động.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục theo phân công; GV hỗ trợ, khích lệ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; bình chọn tiết mục ấn tượng; GV nhận xét, tổng kết chủ đề.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":27,"tiet":27,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Lí thuyết âm nhạc: Ôn tập; Đọc nhạc: Bài đọc nhạc số 4","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Ôn tập, củng cố các kiến thức lí thuyết âm nhạc đã học (kí hiệu ghi nhạc, hình nốt, dấu lặng).\n- Đọc đúng tên nốt, cao độ, trường độ Bài đọc nhạc số 4; biết đọc kết hợp gõ phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Chăm chỉ, kiên trì luyện đọc nhạc.\n- Yêu thích âm nhạc thế giới.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc và ghi được kí hiệu về ôn tập các kí hiệu ghi nhạc đã học nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS chơi trò nhận biết nhanh hình nốt/dấu lặng qua thẻ hình để khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, hệ thống các kiến thức lí thuyết đã học.\n- GV hướng dẫn Bài đọc nhạc số 4: đọc tên nốt, đọc cao độ kết hợp trường độ.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện đọc Bài đọc nhạc số 4 kết hợp gõ phách theo nhóm, cá nhân; GV sửa cao độ, trường độ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS đọc lại bài đọc nhạc; nhắc lại tên một vài kí hiệu ghi nhạc đã học.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV dùng học liệu số về ôn tập các kí hiệu ghi nhạc đã học: khuông nhạc hiện trên màn hình, GV kéo nốt lên xuống thì máy phát ngay âm thanh tương ứng, bấm vào hình nốt thì nghe được đúng độ dài của nốt đó — HS thấy được mối liên hệ giữa kí hiệu ghi trên giấy và âm thanh thật, điều mà nhìn hình in tĩnh trong sách không cho thấy.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bộ bài tập tương tác có chấm ngay về ôn tập các kí hiệu ghi nhạc đã học: đặt nốt vào đúng vị trí trên khuông, chọn hình nốt đúng với tiếng gõ vừa nghe, chia ô nhịp cho đủ phách; sai ở đâu máy báo ngay, HS xem lại phần lí thuyết đúng chỗ đó rồi làm lại.\n⚠ (Miền 4: An toàn) Chỉ mở học liệu và phần mềm GV đã chuẩn bị sẵn trên máy của lớp, không mở trang khác trong giờ; làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép; ngồi cách màn hình vừa tầm mắt và nghỉ mắt sau mỗi 20 phút nhìn màn hình.","hs":"- HS đọc và ghi được kí hiệu về ôn tập các kí hiệu ghi nhạc đã học nhờ đối chiếu hình vẽ trên màn hình với âm thanh nghe được.\n- HS làm bài tập tương tác, tự biết mình còn sai phần nào và ôn lại đúng phần đó."}]},
{"lop":4,"mon":"Âm nhạc","tuan":28,"tiet":28,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Học hát: Miền quê em (Nhạc: Ka-ba-lép-xki – Nga; lời Việt: Hoàng Lân); Ôn đọc nhạc: Bài đọc nhạc số 4","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời Việt bài Miền quê em; cảm nhận nét đẹp của một bài hát nước ngoài.\n- Đọc thuộc Bài đọc nhạc số 4 kết hợp gõ phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quê hương; trân trọng âm nhạc các nước trên thế giới.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe một giai điệu nước ngoài quen thuộc, hỏi cảm nhận và dẫn vào bài.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu bài Miền quê em (nhạc nước ngoài, lời Việt); hát mẫu, hỏi cảm nhận.\n- GV hướng dẫn đọc lời ca, chia câu, dạy hát nối tiếp từng câu; ôn nhanh Bài đọc nhạc số 4.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS hát cả bài kết hợp gõ đệm theo phách; đọc lại Bài đọc nhạc số 4; luyện theo tổ, nhóm; GV sửa sai.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS chia sẻ cảm nhận về bài hát nước ngoài; kể tên một bài hát nước ngoài khác em biết.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Miền quê em” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc: Ka-ba-lép-xki – Nga; lời Việt: Hoàng Lân”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Miền quê em” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Miền quê em” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Miền quê em” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":29,"tiet":29,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Thường thức âm nhạc: Giới thiệu kèn trumpet (trôm-pét); Nghe nhạc: Khúc nhạc mở đầu (Gio-a-chi-nô Rô-xi-ni)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết hình dáng, âm sắc của kèn trumpet (trôm-pét).\n- Lắng nghe, cảm nhận tính chất, sắc thái bản nhạc Khúc nhạc mở đầu; biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Trân trọng nhạc cụ và âm nhạc thế giới.\n- Biết lắng nghe, cảm thụ âm nhạc.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được đặc điểm nổi bật của “Giới thiệu kèn trumpet (trôm-pét)” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe một đoạn nhạc do kèn trumpet thể hiện, hỏi cảm nhận về âm sắc.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu kèn trumpet (trôm-pét): hình dáng, âm sắc, cách chơi cơ bản; cho HS quan sát hình ảnh/clip.\n- GV cho HS nghe bản nhạc Khúc nhạc mở đầu; gợi ý HS chú ý nhịp điệu, sắc thái.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS nghe lại bản nhạc và vận động cơ thể theo nhịp; tập nhận ra âm sắc kèn trumpet.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS nói cảm nhận sau khi nghe; kể tên một nhạc cụ nước ngoài khác mà em biết.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV chiếu đoạn phim quay cận cảnh cho nội dung “Giới thiệu kèn trumpet (trôm-pét)”: nhìn rõ hình dáng, chất liệu, số dây hoặc số lỗ, bàn tay nghệ sĩ đặt ở đâu và làm động tác gì để ra tiếng; GV tua chậm và dừng đúng chỗ đó — chi tiết này tranh in trong sách và một lần nghe trên lớp không cho thấy được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 2) HS làm bài tập nghe tương tác có chấm ngay: GV mở lần lượt vài đoạn nhạc ngắn, HS chọn đoạn nào có âm sắc của nhạc cụ vừa học trong “Giới thiệu kèn trumpet (trôm-pét)”; chọn sai thì nghe lại đoạn đó và chọn lần nữa cho tới khi nhận ra đúng.\n⚠ (Miền 4: An toàn) Tư liệu về “Giới thiệu kèn trumpet (trôm-pét)” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Giới thiệu kèn trumpet (trôm-pét)” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":30,"tiet":30,"bai":"Chủ đề 7: Âm nhạc nước ngoài — Vận dụng – Sáng tạo (Tổng kết chủ đề 7)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Vận dụng kiến thức, kĩ năng chủ đề: đọc nhạc, hát, thường thức âm nhạc, nghe nhạc.\n- Biết dàn dựng tiết mục kết hợp hát – gõ đệm – vận động.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Trân trọng âm nhạc thế giới; tự tin biểu diễn.\n- Đoàn kết, hợp tác trong nhóm.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc ôn lại nội dung chủ đề (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung chủ đề 7.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục kết hợp hát – gõ đệm – vận động.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục theo phân công; GV hỗ trợ, khích lệ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; bình chọn tiết mục ấn tượng; GV nhận xét, tổng kết chủ đề.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":31,"tiet":31,"bai":"Chủ đề 8: Chào mùa hè — Học hát: Em yêu mùa hè quê em (Nhạc và lời: Trần Minh Đặng)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng cao độ, trường độ, lời ca bài Em yêu mùa hè quê em; thể hiện tính chất vui tươi, trong sáng.\n- Biết hát kết hợp vỗ tay/gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu quê hương, yêu thiên nhiên; cảm nhận vẻ đẹp của mùa hè quê hương.\n- Chăm chỉ, tích cực tham gia ca hát.\n4. Tích hợp\n- Năng lực số 1.1 CB2c: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe một đoạn âm thanh mùa hè (tiếng ve, tiếng sáo diều) và đoán tên; dẫn vào bài.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV giới thiệu, hát mẫu bài Em yêu mùa hè quê em; hỏi cảm nhận ban đầu.\n- GV hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Cả lớp hát cả bài kết hợp vỗ tay theo phách; luyện theo tổ, nhóm, cá nhân; GV sửa cao độ, phát âm.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS hát lại bài cho người thân nghe; chia sẻ điều em yêu thích ở mùa hè quê em.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản thu mẫu bài “Em yêu mùa hè quê em” từ học liệu điện tử của bộ sách, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Trần Minh Đặng”; HS nghe trọn bài một lần để nắm giai điệu và chỗ ngân, sau đó nghe từng câu và hát theo, chủ động xin GV mở lại đúng câu mình còn hát chênh.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Tập xong, mỗi tổ tự thu âm phần trình bày bài “Em yêu mùa hè quê em” bằng điện thoại hoặc máy tính của lớp, nghe lại rồi chỉ ra chỗ vào chưa đều, chỗ hát chưa rõ lời để sửa và thu lần thứ hai.\n⚠ (Miền 4: An toàn) Chỉ lấy bản thu từ học liệu của bộ sách hoặc kênh chính thức của nhà xuất bản, không tải nhạc từ trang lạ và không chép nhạc của người khác rồi nhận là của mình; khi giới thiệu bài “Em yêu mùa hè quê em” phải nêu tên tác giả; bản thu giọng hát của tổ chỉ dùng trong giờ học, muốn gửi cho ai phải hỏi ý kiến cả tổ và GV.","hs":"- HS nghe bản thu mẫu, hát đúng cao độ và biết xin mở lại đúng câu mình còn sai.\n- HS thu âm, nghe lại phần trình bày bài “Em yêu mùa hè quê em” của tổ và nêu được chỗ đã sửa ở lần thu thứ hai."}]},
{"lop":4,"mon":"Âm nhạc","tuan":32,"tiet":32,"bai":"Chủ đề 8: Chào mùa hè — Ôn tập bài hát Em yêu mùa hè quê em; Nhạc cụ: Thể hiện nhạc cụ gõ hoặc nhạc cụ giai điệu","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được bài Em yêu mùa hè quê em với hình thức phù hợp.\n- Thể hiện hình tiết tấu bằng nhạc cụ gõ/nhạc cụ giai điệu; biết đệm cho bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu mùa hè quê hương; tự tin biểu diễn.\n- Chăm chỉ luyện tập, hợp tác cùng bạn.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại bài Em yêu mùa hè quê em kết hợp vỗ tay khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV ôn tập, sửa sai bài hát; hướng dẫn hát kết hợp vận động.\n- GV làm mẫu hình tiết tấu bằng nhạc cụ; hướng dẫn HS đọc và thực hiện theo.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện gõ/bấm hình tiết tấu; ghép đệm cho bài hát theo nhóm; GV sửa cho đều, đúng phách.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn hát kết hợp gõ đệm; nhóm khác nhận xét.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":33,"tiet":33,"bai":"Chủ đề 8: Chào mùa hè — Nghe nhạc: Khúc ca vào hè (Trương Tuyết Mai); Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Lắng nghe, cảm nhận tính chất, sắc thái bản nhạc Khúc ca vào hè; biết vận động theo nhạc.\n- Vận dụng kiến thức, kĩ năng chủ đề để dàn dựng tiết mục chào mùa hè.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Yêu mùa hè, yêu cuộc sống; tự tin biểu diễn.\n- Đoàn kết, hợp tác trong nhóm.\n4. Tích hợp\n- Năng lực số 1.2 CB2a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho HS nghe âm thanh mùa hè, hỏi cảm nhận và dẫn vào bài.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV cho HS nghe bản nhạc Khúc ca vào hè; gợi ý HS chú ý nhịp điệu, sắc thái.\n- GV chia nhóm, giao nhiệm vụ dàn dựng tiết mục chào mùa hè kết hợp hát – gõ đệm – vận động.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục theo phân công; GV hỗ trợ, khích lệ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; bình chọn tiết mục ấn tượng; GV nhận xét.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 2) GV mở bản ghi hình buổi biểu diễn tác phẩm “Khúc ca vào hè” (Trương Tuyết Mai); HS vừa nghe vừa quan sát để nhận ra nhạc cụ nào giữ giai điệu chính, đoạn nào nhạc mạnh lên, đoạn nào chậm lại và ai là người bắt nhịp cho cả dàn nhạc — những điều chỉ nghe bản thu tiếng thì không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở thêm một đoạn nhạc do máy tự sinh theo phong cách gần giống rồi cho HS nghe đối chiếu với bản do nghệ sĩ biểu diễn; HS nêu chỗ khác nhau về sắc thái to nhỏ, chỗ nhanh chậm và nhận ra máy ghép lại theo những bản nhạc nó đã học nên chưa có cảm xúc của người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản ghi hình “Khúc ca vào hè” phải lấy từ kênh chính thức của nhà hát, dàn nhạc hoặc nhà xuất bản và tải về trước để không lẫn quảng cáo; khi nói hoặc viết về tác phẩm phải ghi tên tác giả và tên người biểu diễn, không cắt nhạc của người khác đem dùng khi chưa được phép; nghe bằng loa ở mức vừa, không đeo tai nghe mở to lâu.","hs":"- HS nêu được nét đặc sắc của tác phẩm “Khúc ca vào hè” nhờ vừa nghe vừa quan sát dàn nhạc biểu diễn.\n- HS chỉ ra được điểm khác giữa đoạn nhạc do máy tạo và đoạn do nghệ sĩ trình bày."}]},
{"lop":4,"mon":"Âm nhạc","tuan":34,"tiet":34,"bai":"Ôn tập cuối năm (Tiết 1)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc và biểu diễn được các bài hát đã học ở học kì II (Hạt mưa kể chuyện, Tình bạn tuổi thơ, Miền quê em, Em yêu mùa hè quê em).\n- Đọc đúng các Bài đọc nhạc số 3, số 4; ôn lại kiến thức lí thuyết, thường thức âm nhạc.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Chăm chỉ ôn tập; tự tin thể hiện.\n- Yêu thích môn Âm nhạc.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV tổ chức trò chơi âm nhạc ôn lại các bài hát học kì II (nghe giai điệu đoán tên bài).","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV hệ thống nội dung học kì II: các bài hát, bài đọc nhạc, lí thuyết, thường thức âm nhạc.\n- GV cho HS ôn lần lượt từng bài hát và bài đọc nhạc; sửa sai.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- HS luyện hát – đọc nhạc theo tổ, nhóm; luyện biểu diễn một bài tự chọn.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- HS biểu diễn bài hát/bài đọc nhạc yêu thích trước lớp.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."}]},
{"lop":4,"mon":"Âm nhạc","tuan":35,"tiet":35,"bai":"Ôn tập cuối năm (Tiết 2) – Biểu diễn tổng kết năm học","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn được các bài hát, bài đọc nhạc đã học trong năm với hình thức phong phú.\n- Phối hợp hát, gõ đệm, vận động; tự đánh giá kết quả học tập cả năm.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động, tích cực luyện tập; mạnh dạn thể hiện và tự điều chỉnh khi hát/gõ/đọc nhạc chưa đúng.\n- Giao tiếp và hợp tác: Biết phối hợp nhịp nhàng cùng bạn trong hoạt động nhóm; lắng nghe, chia sẻ, nhận xét.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm, ý tưởng biểu diễn phù hợp.\n3. Phẩm chất\n- Tự tin biểu diễn; đoàn kết, hợp tác.\n- Yêu thích môn Âm nhạc.\n4. Tích hợp\n- Năng lực số 3.3 CB2a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS giới thiệu sản phẩm của tổ đúng phép lịch sự, có ghi tên tác giả và xin phép bạn trước khi chia sẻ.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ (thanh phách, song loan, trống con, tem-bơ-rin) và nhạc cụ giai điệu (ri-coóc-đơ hoặc kèn phím) nếu có.\n- HS: SGK Âm nhạc 4 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ tự tạo nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, kết nối vào bài học.\n- GV cho lớp hát lại một bài yêu thích kết hợp vỗ tay để khởi động.","hs":"- HS tham gia trò chơi/khởi động, lắng nghe và ghi tên bài."},{"ten":"B. KHÁM PHÁ – HÌNH THÀNH KIẾN THỨC (15 phút)","gv":"Mục tiêu: HS hình thành kiến thức, kĩ năng trọng tâm của tiết.\n- GV nêu yêu cầu biểu diễn tổng kết năm học; chia nhóm, giao nhiệm vụ chuẩn bị tiết mục.\n- GV gợi ý cách phối hợp hát – gõ đệm – vận động cho tiết mục.","hs":"- HS lắng nghe, quan sát, thực hành theo hướng dẫn của GV."},{"ten":"C. LUYỆN TẬP – THỰC HÀNH (10 phút)","gv":"Mục tiêu: HS luyện tập, củng cố kĩ năng vừa học.\n- Các nhóm luyện tập tiết mục biểu diễn tổng kết năm học; GV hỗ trợ.","hs":"- HS luyện tập theo tổ, nhóm, cá nhân; tự nhận xét và sửa sai."},{"ten":"D. VẬN DỤNG (5 phút)","gv":"Mục tiêu: HS vận dụng, sáng tạo và liên hệ thực tế.\n- Các nhóm biểu diễn trước lớp; lớp nhận xét, bình chọn; GV nhận xét, đánh giá, tổng kết năm học.","hs":"- HS vận dụng, biểu diễn/chia sẻ; lắng nghe dặn dò."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 2) Mỗi tổ tự quay lại phần biểu diễn cuối năm học của mình, xem lại và chọn bản quay ưng ý nhất; HS nói rõ đã sửa chỗ nào giữa lần quay đầu và lần quay sau.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 2) HS viết lời giới thiệu ngắn cho bản quay của tổ — có tên bài hát, tên tác giả, tên các bạn biểu diễn — rồi gửi vào nhóm lớp cho các bạn và gia đình xem; trước khi gửi phải hỏi ý kiến từng bạn có mặt trong đoạn phim.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 2) GV mở cho HS nghe một đoạn nhạc do máy tự tạo bên cạnh một đoạn do nghệ sĩ trình bày; HS so sánh sắc thái to nhỏ, chỗ nhanh chậm, hơi thở và rút ra: máy ghép lại từ những gì đã học được nên đều đặn nhưng khó có cảm xúc như người chơi. GV mở và điều khiển công cụ, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Đoạn phim có mặt bạn chỉ được gửi khi từng bạn trong đó đồng ý và chỉ gửi trong nhóm lớp, không đăng ra mạng xã hội; giới thiệu bài hát phải ghi tên tác giả, không nhận bài của người khác là của mình; góp ý cho bạn bằng lời lịch sự, viết trong nhóm cũng phải như nói trước mặt.","hs":"- HS tự quay, xem lại và nêu được điều tổ mình đã sửa được giữa hai lần trình bày.\n- HS giới thiệu sản phẩm của tổ đúng phép lịch sự, có ghi tên tác giả và xin phép bạn trước khi chia sẻ."}]}
];
